import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';

interface SkillCategory {
  label: string;
  skills: string[];
}

@Component({
  selector: 'app-skills',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './skills.component.html',
  styleUrl: './skills.component.css',
})
export class SkillsComponent {
  categories: SkillCategory[] = [
    {
      label: 'Programmeertalen',
      skills: ['JavaScript', 'TypeScript', 'C#', 'Java', 'SQL', 'HTML', 'CSS'],
    },
    {
      label: 'Frameworks & Libraries',
      skills: ['Angular', 'Node.js', '.NET'],
    },
    {
      label: 'Database',
      skills: ['MySQL'],
    },
    {
      label: 'Tools & Omgeving',
      skills: ['Git', 'Docker', 'Linux', 'npm', 'VS Code', 'Bruno'],
    },
    {
      label: 'Extra',
      skills: ['REST API\'s', 'CI/CD', 'GitHub Actions', 'Server Hosting', 'NAS Setup'],
    },
  ];
}
<section id="skills" class="section skills-section">
  <div class="container">

    <div class="skills-header reveal">
      <span class="section-label">Wat ik kan</span>
      <h2 class="section-title">Technische skills</h2>
      <div class="section-divider"></div>
    </div>

    <div class="skills-grid reveal reveal-delay-1">
      <div class="skill-category" *ngFor="let category of categories">
        <h3 class="category-title">{{ category.label }}</h3>
        <div class="pill-row">
          <span class="skill-pill" *ngFor="let skill of category.skills">
            {{ skill }}
          </span>
        </div>
      </div>
    </div>

  </div>
</section>
